from pathlib import Path
import re
rawp=Path('src/i18n/rawUi.ts')
s=rawp.read_text()
# Remaining UI phrases from the final scan. Keep dynamic/code-like entries out.
phrases=[]
pat=re.compile(r'>\s*([^<>{}\n]+?)\s*<')
for f in Path('src').rglob('*.tsx'):
    txt=f.read_text(errors='ignore')
    for m in pat.finditer(txt):
        x=' '.join(m.group(1).split())
        if not re.search('[A-Za-z]',x) or len(x)<3: continue
        if re.fullmatch(r'[A-Za-z0-9_./:=-]+',x): continue
        if any(z in x for z in ['useState','return','const ','=>','Array','Number(','Date(','Math.','i.','o.','item.','prod.','order.','current30','prior30','Promise']): continue
        if x not in phrases: phrases.append(x)
