raw=s
keys=[m.group(1).replace("\\'", "'") for m in re.finditer(r"^\s*'((?:\\'|[^'])*)'\s*:\s*\{en:",raw,re.M)]
modified=0
for f in Path('src').rglob('*.tsx'):
    s=f.read_text(errors='ignore'); orig=s
    for en in sorted(keys,key=len,reverse=True):
        if len(en)<3: continue
        ee=en.replace('\\','\\\\').replace("'","\\'")
        for old,new in [
            (f'>{en}<',f">{{translateRawUi('{ee}')}}<"),
            (f'> {en}<',f"> {{translateRawUi('{ee}')}}<"),
            (f'>\n{en}<',f">\n{{translateRawUi('{ee}')}}<"),
            (f'>\n  {en}<',f">\n  {{translateRawUi('{ee}')}}<"),
            (f'>\n    {en}<',f">\n    {{translateRawUi('{ee}')}}<"),
        ]: s=s.replace(old,new)
        for attr in ('placeholder','aria-label','title'):
            s=s.replace(f'{attr}="{en}"',f"{attr}={{translateRawUi('{ee}')}}")
    if s!=orig:
        if 'translateRawUi(' in s and not any('import { translateRawUi }' in l for l in s.splitlines()[:40]):
            rel=f.relative_to(Path('src')); depth=len(rel.parts)-1; prefix='../'*depth
            lines=s.splitlines(True); lines.insert(1,f"import {{ translateRawUi }} from '{prefix}i18n';\n"); s=''.join(lines)
        f.write_text(s); modified+=1
print('wrapped files',modified,'keys',len(keys))
